-- Migration: image_base_prompt
-- Add the shared image style prompt to ai_system_prompts so it can be edited via admin panel.

insert into ai_system_prompts (generator_type, label, content) values
('image_base', 'Image Style Prompt', 'Refined semi-realistic painterly fantasy illustration. Clearly illustrated, polished, and non-photographic. Controlled brushwork, clean shape design, clear form modeling, readable anatomy, expressive faces, strong silhouettes, atmospheric depth, restrained texture, and a cohesive finished surface. Favor stronger value separation, firmer structure, cleaner edge control, sharper facial planes, and clearer focal hierarchy. Keep colors tasteful and moderately muted with selective accents for clarity and emphasis. Prioritize readability, subject clarity, and elegant painterly fantasy over spectacle or realism. Avoid photorealism, cinematic or camera-driven aesthetics, glossy realism, lens blur, pores, oversharpening, noisy micro-detail, muddy rendering, excessive grit, rough sketchiness, cartoon stylization, anime stylization, overly soft diffusion, fuzzy texture overload, and cluttered ornamental detail that weakens the silhouette or focal read.');
